    "subtitle_h3": {
      "type": "Text",
      "props": {
        "text": "Top Resources for Beginner to Intermediate Python",
        "variant": "h3"
      },
      "children": []
    },
    "learning_paths_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "icon",
            "label": "Icon"
          },
          {
            "key": "name",
            "label": "Course Name"
          },
          {
            "key": "tagline",
            "label": "Tagline"
          },
          {
            "key": "duration",
            "label": "Duration"
          },
          {
            "key": "description",
            "label": "Description"
          },
          {
            "key": "actionLabel",
            "label": "Action"
          },
          {
            "key": "actionUrl",
            "label": "URL"
          }
        ],
        "rows": [
          {
            "icon": "../assets/r_000092_01_1_book.svg",
            "name": "Python for Everybody Specialization",
            "tagline": "Comprehensive introduction to Python",
            "duration": "~8 months at 3 hours/week",
            "description": "Offered by the University of Michigan via Coursera, this specialization covers Python fundamentals, data structures, web data access, and databases. It's ideal for those with no prior programming experience.",
            "actionLabel": "Learn More",
            "actionUrl": "https://www.coursera.org/specializations/python"
          },
          {
            "icon": "../assets/r_000092_01_2_laptop.svg",
            "name": "100 Days of Code - The Complete Python Pro Bootcamp",
            "tagline": "Project-based learning with daily challenges",
            "duration": "100 days, 1-2 hours daily",
            "description": "This Udemy course by Angela Yu focuses on hands-on project building, allowing learners to create 100 real-world Python projects over 100 days, from web development to game creation.",
            "actionLabel": "Learn More",
            "actionUrl": "https://www.udemy.com/course/100-days-of-code/"
          },
          {
            "icon": "../assets/r_000092_01_3_terminal.svg",
            "name": "Learn Python 3 (Codecademy)",
            "tagline": "Interactive, browser-based coding environment",
            "duration": "~30 hours (core course)",
            "description": "Codecademy provides an interactive learning experience with immediate feedback, making it excellent for beginners to grasp core Python concepts and syntax directly in their browser.",
            "actionLabel": "Learn More",
            "actionUrl": "https://www.codecademy.com/learn/learn-python-3"
          },
          {
            "icon": "../assets/r_000092_01_4_code-slash.svg",
            "name": "Google's Python Class",
            "tagline": "Free, self-paced course with practical exercises",
            "duration": "Self-paced, typically a few weeks",
            "description": "This free course from Google Developers includes written materials, lecture videos, and extensive coding exercises. It's designed for people with a little programming experience, but is accessible to motivated beginners.",
            "actionLabel": "Learn More",
            "actionUrl": "https://developers.google.com/edu/python/"
          },
          {
            "icon": "../assets/r_000092_01_5_gear.svg",
            "name": "Automate the Boring Stuff with Python",
            "tagline": "Practical automation skills for real-world tasks",
            "duration": "~13 hours (video course)",
            "description": "Written by Al Sweigart, this resource teaches Python by showing you how to automate practical tasks such as web scraping, file management, and sending emails. The book is available for free online, with an accompanying video course on Udemy.",
            "actionLabel": "Learn More",
            "actionUrl": "https://automatetheboringstuff.com/"
          }
        ],
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "name",
        "highlightColumns": [
          "duration"
        ]
      },
      "children": []
    }
